/* Tech IA · unitat 1 «Què hi ha dins una IA?» (i1-1 … i1-4)
   Contingut propi de Numi. Mostra de referència per als agents de contingut (vegeu scripts/TECH-IA.md): la sessió i1-1
   és completa (pas iangram: un model de llenguatge de bigrames que es pot entrenar i fer generar). i1-2: regles o exemples
   (filtre de missatges trampa, CantinaBot, reaccions dibuixades); i1-3: probabilitats, context i temperatura (el
   comentarista robòtic, fluid ≠ cert); i1-4: projecte d'un mini model amb estil propi. Exemples i noms inventats. */
Object.assign(TBADGE, {
  i_ngram: { id: 'i_ngram', ico: '🔮', n: 'Endevinaire de paraules|Adivinador de palabras', d: "Has construït un model de llenguatge que prediu la paraula següent i l'has fet generar.|Has construido un modelo de lenguaje que predice la palabra siguiente y lo has hecho generar." },
  i_rules: { id: 'i_rules', ico: '⚖️', n: 'Regles contra exemples|Reglas contra ejemplos', d: "Has comparat un programa de regles amb una IA que aprèn d'exemples i has vist on falla cadascun.|Has comparado un programa de reglas con una IA que aprende de ejemplos y has visto dónde falla cada uno." },
  i_temp: { id: 'i_temp', ico: '🌡️', n: 'Domador de la temperatura|Domador de la temperatura', d: "Has fet que un model triï amb més o menys risc i has descobert que un text fluid no sempre és cert.|Has hecho que un modelo elija con más o menos riesgo y has descubierto que un texto fluido no siempre es cierto." },
  i_style: { id: 'i_style', ico: '🎙️', n: 'Creador de models|Creador de modelos', d: "Has entrenat un mini model de llenguatge amb un estil propi i n'has presentat els punts forts i els límits.|Has entrenado un mini modelo de lenguaje con un estilo propio y has presentado sus puntos fuertes y sus límites." }
});

COURSE_UNITS[1] = { t: 'Què hi ha dins una IA?|¿Qué hay dentro de una IA?', d: 'Prediccions, dades i probabilitat|Predicciones, datos y probabilidad', color: '#A23BEA', s: [

  /* ---------- Sessió 1 · Endevina la paraula següent ---------- */
  { id: 'i1-1', t: 'Endevina la paraula següent|Adivina la palabra siguiente', min: 45, badge: 'i_ngram',
    learn: ["Un model de llenguatge no pensa: calcula quina paraula (o fitxa) és més probable que vingui després i la va afegint.|Un modelo de lenguaje no piensa: calcula qué palabra (o ficha) es más probable que venga después y la va añadiendo.",
      "Les IA d'avui aprenen de dades: el que no hi ha a les dades no ho poden predir, i amb més dades i més variades, prediuen millor.|Las IA de hoy aprenden de datos: lo que no está en los datos no lo pueden predecir, y con más datos y más variados, predicen mejor.",
      "La temperatura decideix si el model tria sempre la més probable (previsible) o s'arrisca (original, de vegades absurd).|La temperatura decide si el modelo elige siempre la más probable (previsible) o se arriesga (original, a veces absurdo)."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Quan escrius al mòbil, el teclat et proposa la paraula següent. Com creus que ho fa?|Cuando escribes en el móvil, el teclado te propone la palabra siguiente. ¿Cómo crees que lo hace?",
        opts: ["Ha comptat quines paraules solen venir després en molts textos|Ha contado qué palabras suelen venir después en muchos textos", "Entén el que vols dir, com una persona|Entiende lo que quieres decir, como una persona", "Té guardades totes les frases que existeixen|Tiene guardadas todas las frases que existen"], a: 0,
        ex: "Avui ho comprovaràs construint el teu propi model.|Hoy lo comprobarás construyendo tu propio modelo." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'estudi', title: 'Obrim una IA per dins|Abrimos una IA por dentro',
        t: "Benvinguts i benvingudes a <b>Tech IA</b>! Els xats d'IA escriuen, resumeixen i responen preguntes. Però què hi ha a dins? Avui en construirem un de minúscul que només fa una cosa: <b>endevinar la paraula següent</b>. És la mateixa idea que fan servir els models grans… a una escala molt més petita.|¡Bienvenidos y bienvenidas a <b>Tech IA</b>! Los chats de IA escriben, resumen y responden preguntas. Pero ¿qué hay dentro? Hoy construiremos uno minúsculo que solo hace una cosa: <b>adivinar la palabra siguiente</b>. Es la misma idea que usan los modelos grandes… a una escala mucho más pequeña." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Model de llenguatge|Modelo de lenguaje', t: 'Una IA no pensa: prediu|Una IA no piensa: predice', anim: 'i1pred',
          x: "Un <span class='hl'>model de llenguatge</span> rep un text i calcula quina <b>fitxa</b> (una paraula o un tros de paraula) és més probable que vingui després. L'afegeix i torna a començar. Fitxa a fitxa, surt un text sencer.|Un <span class='hl'>modelo de lenguaje</span> recibe un texto y calcula qué <b>ficha</b> (una palabra o un trozo de palabra) es más probable que venga después. La añade y vuelve a empezar. Ficha a ficha, sale un texto entero." },
        { k: 'Regles o dades?|¿Reglas o datos?', t: 'Dues maneres de fer un programa «llest»|Dos maneras de hacer un programa «listo»', anim: 'i1regles',
          x: "Amb <b>regles</b>, una persona escriu què cal fer en cada cas («si diu hola, respon hola»). Amb <b>dades</b>, el programa troba els patrons sol a partir de molts exemples. Les IA d'avui aprenen sobretot de dades.|Con <b>reglas</b>, una persona escribe qué hay que hacer en cada caso («si dice hola, responde hola»). Con <b>datos</b>, el programa encuentra los patrones solo a partir de muchos ejemplos. Las IA de hoy aprenden sobre todo de datos.",
          tip: "Un filtre d'spam amb regles falla quan l'spam canvia una paraula; un d'après amb dades se n'adona si ha vist prou exemples.|Un filtro de spam con reglas falla cuando el spam cambia una palabra; uno aprendido con datos se da cuenta si ha visto suficientes ejemplos." },
        { k: 'Comptar|Contar', t: 'El model més senzill: comptar parelles|El modelo más sencillo: contar parejas', media: { k: 'ia', demo: 'ngram', text: 'el gat menja. el gat dorm. el gat dorm. el gos corre.|el gato come. el gato duerme. el gato duerme. el perro corre.', ctx: 'el gat|el gato' },
          x: "Un <b>bigrama</b> compta quina paraula ve després de cada paraula. Després de «gat», a les dades hi ha «dorm» 2 cops i «menja» 1 cop: per això «dorm» té un 67 %.|Un <b>bigrama</b> cuenta qué palabra viene después de cada palabra. Después de «gato», en los datos hay «duerme» 2 veces y «come» 1 vez: por eso «duerme» tiene un 67 %." },
        { k: 'Probabilitat|Probabilidad', t: 'Més dades, millors prediccions|Más datos, mejores predicciones', anim: 'i1prob',
          x: "La probabilitat és quantes vegades passa una cosa dividit pel total de vegades. Si el model ha llegit poc, s'equivoca molt; si llegeix més textos i més variats, les prediccions s'assemblen més a com escrivim de veritat.|La probabilidad es cuántas veces pasa algo dividido por el total de veces. Si el modelo ha leído poco, se equivoca mucho; si lee más textos y más variados, las predicciones se parecen más a cómo escribimos de verdad." },
        { k: 'Temperatura|Temperatura', t: 'Previsible o sorprenent?|¿Previsible o sorprendente?', anim: 'i1temp',
          x: "En generar, la <b>temperatura</b> decideix com s'arrisca el model. Baixa: tria gairebé sempre la més probable (text previsible). Alta: tria també paraules poc probables (text original… o absurd).|Al generar, la <b>temperatura</b> decide cuánto se arriesga el modelo. Baja: elige casi siempre la más probable (texto previsible). Alta: elige también palabras poco probables (texto original… o absurdo)." }
      ] },
      { k: 'unplug', ph: 'mans', ico: '🧑‍🤝‍🧑', title: 'El model humà|El modelo humano', t: "En grups de tres, amb el full «Comptem parelles».|En grupos de tres, con la hoja «Contamos parejas».",
        steps: ["Llegiu el text curt del full.|Leed el texto corto de la hoja.", "Per a «el», «la» i «un», apunteu amb ratlletes quina paraula ve després cada vegada.|Para «el», «la» y «un», apuntad con rayitas qué palabra viene después cada vez.",
          "Ara un de vosaltres fa de model: només pot dir la paraula amb més ratlletes. Genereu una frase entre tots.|Ahora uno de vosotros hace de modelo: solo puede decir la palabra con más rayitas. Generad una frase entre todos.",
          "Repetiu-ho tirant un dau per triar entre les dues més votades: és com pujar la temperatura.|Repetidlo tirando un dado para elegir entre las dos más votadas: es como subir la temperatura."],
        tip: "Fixeu-vos-hi: el «model» no entén el text, només compta.|Fijaos: el «modelo» no entiende el texto, solo cuenta." },
      { k: 'quiz', ph: 'prova', q: "Després de «bon», unes dades tenen: «dia» 6 vegades, «any» 3 vegades i «viatge» 1 vegada. Quina probabilitat té «dia»?|Después de «buen», unos datos tienen: «día» 6 veces, «año» 3 veces y «viaje» 1 vez. ¿Qué probabilidad tiene «día»?",
        opts: ['60 %|60 %', '6 %|6 %', '33 %|33 %'], a: 0, ex: "6 de 10 vegades: 6 ÷ 10 = 0,6, és a dir, un 60 %.|6 de 10 veces: 6 ÷ 10 = 0,6, es decir, un 60 %." },
      { k: 'iangram', ph: 'prova', q: "Aquest model ha llegit un conte curt. <b>Escriu un començament</b> i mira quines paraules preveu. Toca una barra per afegir-la i després toca «Genera».|Este modelo ha leído un cuento corto. <b>Escribe un comienzo</b> y mira qué palabras prevé. Toca una barra para añadirla y luego toca «Genera».",
        text: "la nau va sortir de nit. la nau portava tres robots. el primer robot cantava. el segon robot dormia. el tercer robot mirava les estrelles. les estrelles eren blaves. la nau va arribar a un planeta blau. al planeta blau hi vivia una tortuga. la tortuga parlava amb els robots. els robots es van fer amics de la tortuga.|la nave salió de noche. la nave llevaba tres robots. el primer robot cantaba. el segundo robot dormía. el tercer robot miraba las estrellas. las estrellas eran azules. la nave llegó a un planeta azul. en el planeta azul vivía una tortuga. la tortuga hablaba con los robots. los robots se hicieron amigos de la tortuga.",
        ctx: 'la nau|la nave', checks: [{ k: 'gen' }] },
      { k: 'quiz', ph: 'investiga', q: "El model de la nau només fa frases amb paraules del conte. Per què?|El modelo de la nave solo hace frases con palabras del cuento. ¿Por qué?",
        opts: ["Només pot predir fitxes que ha vist a les dades|Solo puede predecir fichas que ha visto en los datos", "Perquè li agraden els contes|Porque le gustan los cuentos", "Perquè la temperatura és massa baixa|Porque la temperatura es demasiado baja"], a: 0,
        ex: "Un model només sap el que hi ha a les seves dades. Els models grans han llegit milers de milions de textos: per això semblen saber de tot.|Un modelo solo sabe lo que hay en sus datos. Los modelos grandes han leído miles de millones de textos: por eso parecen saber de todo." },
      { k: 'move', ph: 'pausa', title: 'Pausa activa: la cadena de paraules|Pausa activa: la cadena de palabras', secs: 45,
        t: "Dempeus! La primera persona diu una paraula i la següent n'ha de dir una que hi pugui anar darrere. Si la frase té sentit, tothom fa un salt.|¡De pie! La primera persona dice una palabra y la siguiente tiene que decir una que pueda ir detrás. Si la frase tiene sentido, todo el mundo da un salto." },
      { k: 'iangram', ph: 'repte', q: "Aquest model només ha llegit tres frases. <b>Afegeix-li dades</b> perquè després de «el gat» la paraula més probable sigui «dorm».|Este modelo solo ha leído tres frases. <b>Añádele datos</b> para que después de «el gato» la palabra más probable sea «duerme».",
        text: "el gat menja peix. el gat corre pel pati. el gos dorm al sofà.|el gato come pescado. el gato corre por el patio. el perro duerme en el sofá.", ctx: 'el gat|el gato',
        add: ['el gat dorm molt.|el gato duerme mucho.', 'el gat dorm a la cadira.|el gato duerme en la silla.', 'a la nit el gat dorm.|por la noche el gato duerme.'],
        checks: [{ k: 'top', ctx: 'el gat|el gato', next: 'dorm|duerme' }, { k: 'gen' }],
        pro: { n: 3, orders: [2, 3], q: "Ara el model pot mirar <b>dues paraules enrere</b>. Afegeix dades perquè després de «el gat» guanyi «dorm», posa'l a mirar 2 paraules i genera amb temperatura baixa i alta.|Ahora el modelo puede mirar <b>dos palabras atrás</b>. Añade datos para que después de «el gato» gane «duerme», ponlo a mirar 2 palabras y genera con temperatura baja y alta.",
          checks: [{ k: 'top', ctx: 'el gat|el gato', next: 'dorm|duerme' }, { k: 'order', min: 3 }, { k: 'temp' }] } },
      { k: 'iangram', ph: 'repte', q: "Aquest model creu que després de «avui» sempre ve «plou». <b>Afegeix-li frases</b> perquè «plou» baixi fins al 40 % o menys.|Este modelo cree que después de «hoy» siempre viene «llueve». <b>Añádele frases</b> para que «llueve» baje hasta el 40 % o menos.",
        text: "avui plou. avui plou molt. avui plou a la ciutat. demà fa sol.|hoy llueve. hoy llueve mucho. hoy llueve en la ciudad. mañana hace sol.", ctx: 'avui|hoy',
        add: ['avui fa sol.|hoy hace sol.', 'avui tenim examen.|hoy tenemos examen.', 'avui anem al parc.|hoy vamos al parque.', 'avui fa vent.|hoy hace viento.', 'avui toca natació.|hoy toca natación.'],
        checks: [{ k: 'prob', ctx: 'avui|hoy', next: 'plou|llueve', max: .4 }] },
      { k: 'iangram', ph: 'repte', extra: true, unit: 'char', n: 4, q: "⭐ Ara el model aprèn <b>lletres</b>, no paraules. Amb noms de planetes inventats, fes que després de «zor» la lletra més probable sigui la «a».|⭐ Ahora el modelo aprende <b>letras</b>, no palabras. Con nombres de planetas inventados, haz que después de «zor» la letra más probable sea la «a».",
        text: 'zorix zorup kelan zorup mirax|zorix zorup kelan zorup mirax', ctx: 'zor|zor', add: ['zoraki|zoraki', 'zorana|zorana', 'zorat|zorat'],
        checks: [{ k: 'top', ctx: 'zor|zor', next: 'a|a' }, { k: 'gen' }] },
      { k: 'quiz', ph: 'repte', q: "Vols que el model escrigui un títol original per a un conte, encara que de vegades surti estrany. Quina temperatura tries?|Quieres que el modelo escriba un título original para un cuento, aunque a veces salga raro. ¿Qué temperatura eliges?",
        opts: ['Alta (1,5)|Alta (1,5)', 'Zero (0)|Cero (0)', 'Baixa (0,2)|Baja (0,2)'], a: 0,
        ex: "Amb temperatura alta s'arrisca amb paraules poc probables: més original. Per a una resposta fiable (un resum, una dada), millor baixa.|Con temperatura alta se arriesga con palabras poco probables: más original. Para una respuesta fiable (un resumen, un dato), mejor baja." },
      { k: 'iangram', ph: 'crea', edit: true, orders: [2, 3], save: true, name: 'El meu mini model|Mi mini modelo',
        q: "<b>El teu mini model.</b> Esborra el text i escriu-ne un de teu (una cançó, frases típiques de la classe, un conte…) d'almenys 40 paraules. Després genera amb una temperatura baixa i una d'alta.|<b>Tu mini modelo.</b> Borra el texto y escribe uno tuyo (una canción, frases típicas de la clase, un cuento…) de al menos 40 palabras. Después genera con una temperatura baja y una alta.",
        text: 'Escriu aquí el teu text.|Escribe aquí tu texto.', ctx: '',
        sol: "a la classe de tecnologia fem robots i webs. a la classe de música cantem cançons. a l'hora del pati fem esport amb els amics. el dilluns fem dibuix i el dimarts fem ciències. a la tarda llegim llibres i escrivim contes curts sobre planetes i robots.|en la clase de tecnología hacemos robots y webs. en la clase de música cantamos canciones. a la hora del patio hacemos deporte con los amigos. el lunes hacemos dibujo y el martes hacemos ciencias. por la tarde leemos libros y escribimos cuentos cortos sobre planetas y robots.",
        checks: [{ k: 'words', min: 40 }, { k: 'vocab', min: 25 }, { k: 'temp' }] },
      { k: 'quiz', ph: 'tanca', q: "Els xats d'IA grans, en el fons, fan…|Los chats de IA grandes, en el fondo, hacen…",
        opts: ["El mateix que el nostre model, però amb una xarxa neuronal enorme i milers de milions de textos|Lo mismo que nuestro modelo, pero con una red neuronal enorme y miles de millones de textos", "Busquen la resposta en una base de dades de respostes correctes|Buscan la respuesta en una base de datos de respuestas correctas", "Pensen i entenen com les persones|Piensan y entienden como las personas"], a: 0,
        ex: "Prediuen fitxa a fitxa. No compten parelles com nosaltres, sinó que fan servir una xarxa neuronal, però la idea de fons és la mateixa.|Predicen ficha a ficha. No cuentan parejas como nosotros, sino que usan una red neuronal, pero la idea de fondo es la misma." },
      { k: 'quiz', ph: 'tanca', q: "Per què un model de llenguatge pot dir una cosa falsa amb molta seguretat?|¿Por qué un modelo de lenguaje puede decir algo falso con mucha seguridad?",
        opts: ["Perquè tria el que és probable, no el que és veritat|Porque elige lo que es probable, no lo que es verdad", "Perquè ens vol enganyar|Porque nos quiere engañar", "Perquè està espatllat|Porque está estropeado"], a: 0,
        ex: "Per això, a la unitat 3 aprendrem a comprovar el que diu: les famoses «al·lucinacions».|Por eso, en la unidad 3 aprenderemos a comprobar lo que dice: las famosas «alucinaciones»." },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 2 · Regles o exemples? ---------- */
  { id: 'i1-2', t: 'Regles o exemples?|¿Reglas o ejemplos?', min: 50, badge: 'i_rules',
    learn: ["Un programa de regles fa exactament el que una persona ha escrit: és previsible i fàcil d'explicar, però falla amb els casos que ningú havia previst.|Un programa de reglas hace exactamente lo que una persona ha escrito: es previsible y fácil de explicar, pero falla con los casos que nadie había previsto.",
      "Una IA que aprèn d'exemples troba els patrons sola i funciona amb imatges, sons i textos, però només sap el que hi ha a les dades i no sempre podem saber per què decideix.|Una IA que aprende de ejemplos encuentra los patrones sola y funciona con imágenes, sonidos y textos, pero solo sabe lo que hay en los datos y no siempre podemos saber por qué decide.",
      "Les IA d'avui combinen les dues coses: aprenen de moltes dades i, a sobre, porten normes que hi han posat persones.|Las IA de hoy combinan las dos cosas: aprenden de muchos datos y, encima, llevan normas que han puesto personas."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "El model de la nau proposava «robot» després de «primer». Com ho havia après?|El modelo de la nave proponía «robot» después de «primer». ¿Cómo lo había aprendido?",
        opts: ["Comptant què venia després de «primer» al conte|Contando qué venía después de «primer» en el cuento", "Algú li havia escrit la regla «després de primer, digues robot»|Alguien le había escrito la regla «después de primer, di robot»", "Ho havia buscat a internet|Lo había buscado en internet"], a: 0,
        ex: "Ho havia après de les dades, sense cap regla escrita. Avui compararem les dues maneres de fer un programa «llest».|Lo había aprendido de los datos, sin ninguna regla escrita. Hoy compararemos las dos maneras de hacer un programa «listo»." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'lab', title: "Regles contra exemples|Reglas contra ejemplos",
        t: "Al xat de la classe (inventat) arriben missatges trampa: «Has guanyat un mòbil! Clica aquí». Dos equips volen fer-hi un filtre. L'<b>equip Regles</b> escriu normes a mà. L'<b>equip Exemples</b> ensenya la màquina amb missatges ja marcats. Quin aguantarà millor quan els trucs canviïn? Avui ho descobriràs provant totes dues maneres.|Al chat de la clase (inventado) llegan mensajes trampa: «¡Has ganado un móvil! Pulsa aquí». Dos equipos quieren hacerle un filtro. El <b>equipo Reglas</b> escribe normas a mano. El <b>equipo Ejemplos</b> enseña a la máquina con mensajes ya marcados. ¿Cuál aguantará mejor cuando los trucos cambien? Hoy lo descubrirás probando las dos maneras." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Regles|Reglas', t: 'Si passa això, fes allò|Si pasa esto, haz aquello', anim: 'i12rule',
          x: "Amb <b>regles</b>, una persona pensa els casos i els escriu: «si el missatge conté <i>gratis</i>, és trampa». L'ordinador les segueix al peu de la lletra, sense entendre-les. Funciona… fins que arriba un cas que ningú havia previst: «GR4TIS».|Con <b>reglas</b>, una persona piensa los casos y los escribe: «si el mensaje contiene <i>gratis</i>, es trampa». El ordenador las sigue al pie de la letra, sin entenderlas. Funciona… hasta que llega un caso que nadie había previsto: «GR4TIS».",
          tip: "Les regles són perfectes per a problemes exactes: calcular un preu o comprovar la llargada d'una contrasenya.|Las reglas son perfectas para problemas exactos: calcular un precio o comprobar la longitud de una contraseña." },
        { k: 'Exemples|Ejemplos', t: 'Aprendre mirant molts casos|Aprender mirando muchos casos', anim: 'i12data',
          x: "Amb <b>aprenentatge automàtic</b> no escrivim les regles: donem a l'ordinador molts <b>exemples etiquetats</b> (aquest és trampa, aquest no) i ell troba què tenen en comú. Si arriba «GR4TIS», s'assembla prou als exemples de trampa per detectar-lo.|Con <b>aprendizaje automático</b> no escribimos las reglas: damos al ordenador muchos <b>ejemplos etiquetados</b> (este es trampa, este no) y él encuentra qué tienen en común. Si llega «GR4TIS», se parece lo bastante a los ejemplos de trampa para detectarlo." },
        { k: 'Com decideix?|¿Cómo decide?', t: 'Els exemples més semblants voten|Los ejemplos más parecidos votan', media: { k: 'ia', demo: 'knn' },
          x: "Una manera senzilla d'aprendre d'exemples: davant d'un cas nou, la IA busca els 5 exemples que s'hi assemblen més i mira què són. Si 4 de 5 són «trampa», diu «trampa» amb un 80 % de confiança. Es diu <b>k veïns més propers</b> i avui la faràs servir.|Una manera sencilla de aprender de ejemplos: ante un caso nuevo, la IA busca los 5 ejemplos que más se le parecen y mira qué son. Si 4 de 5 son «trampa», dice «trampa» con un 80 % de confianza. Se llama <b>k vecinos más cercanos</b> y hoy la usarás." },
        { k: 'Punts febles|Puntos débiles', t: 'On falla cadascú|Dónde falla cada uno', anim: 'i12when',
          x: "Les regles fallen amb el que és nou o difícil de descriure: com explicaries amb regles una cara, una veu o un dibuix? Els exemples fallen quan les dades són poques, estan mal etiquetades o no s'assemblen al món real, i sovint no sabem dir per què han decidit una cosa.|Las reglas fallan con lo que es nuevo o difícil de describir: ¿cómo explicarías con reglas una cara, una voz o un dibujo? Los ejemplos fallan cuando los datos son pocos, están mal etiquetados o no se parecen al mundo real, y a menudo no sabemos decir por qué han decidido algo." },
        { k: 'Avui|Hoy', t: "Les IA d'avui fan totes dues coses|Las IA de hoy hacen las dos cosas", anim: 'i12mix',
          x: "Els xats d'IA aprenen de moltíssims textos; després, persones els ensenyen amb exemples de bones respostes i s'hi afegeixen normes (no ajudar a fer mal, no donar dades personals). Un filtre d'spam, igual: un model après d'exemples i algunes regles fixes, com bloquejar una llista de webs perilloses.|Los chats de IA aprenden de muchísimos textos; después, personas les enseñan con ejemplos de buenas respuestas y se añaden normas (no ayudar a hacer daño, no dar datos personales). Un filtro de spam, igual: un modelo aprendido de ejemplos y algunas reglas fijas, como bloquear una lista de webs peligrosas." }
      ] },
      { k: 'unplug', ph: 'mans', ico: '👾', title: 'Glimps o Blorbs?|¿Glimps o Blorbs?', t: "En grups de quatre, amb les targetes «Criatures de Zorix». Dues persones fan d'equip Regles i dues d'equip Exemples.|En grupos de cuatro, con las tarjetas «Criaturas de Zorix». Dos personas hacen de equipo Reglas y dos de equipo Ejemplos.",
        steps: ["Tots dos equips miren 1 minut les 8 targetes etiquetades (4 Glimps i 4 Blorbs).|Los dos equipos miran 1 minuto las 8 tarjetas etiquetadas (4 Glimps y 4 Blorbs).",
          "Equip Regles: escriu 2 regles («si té… és un Glimp») i aplica-les al peu de la lletra.|Equipo Reglas: escribe 2 reglas («si tiene… es un Glimp») y aplícalas al pie de la letra.",
          "Equip Exemples: sense regles, per a cada criatura nova busqueu les 3 targetes més semblants i voteu.|Equipo Ejemplos: sin reglas, para cada criatura nueva buscad las 3 tarjetas más parecidas y votad.",
          "Classifiqueu les 6 criatures noves. Quin equip ha fallat amb les estranyes?|Clasificad las 6 criaturas nuevas. ¿Qué equipo ha fallado con las raras?"],
        tip: "Fixeu-vos-hi: una regla és ràpida i clara, però si es fixa en la pista equivocada, falla sempre. Els exemples s'adapten, però si les etiquetes són dolentes, copien l'error.|Fijaos: una regla es rápida y clara, pero si se fija en la pista equivocada, falla siempre. Los ejemplos se adaptan, pero si las etiquetas son malas, copian el error." },
      { k: 'dsort', ph: 'prova', q: "<b>Regles o exemples?</b> Classifica cada tasca segons la manera que hi funciona millor.|<b>¿Reglas o ejemplos?</b> Clasifica cada tarea según la manera que funciona mejor.",
        bins: ['📏 Regles|📏 Reglas', '🧠 Exemples|🧠 Ejemplos'],
        items: [
          { t: 'Calcular el preu amb un descompte del 20 %|Calcular el precio con un descuento del 20 %', b: 0 },
          { t: 'Reconèixer qui canta una cançó per la veu|Reconocer quién canta una canción por la voz', b: 1 },
          { t: 'Comprovar que una contrasenya té almenys 12 caràcters|Comprobar que una contraseña tiene al menos 12 caracteres', b: 0 },
          { t: 'Recomanar vídeos que et poden agradar|Recomendar vídeos que te pueden gustar', b: 1 },
          { t: 'Ordenar la llista de la classe alfabèticament|Ordenar la lista de la clase alfabéticamente', b: 0 },
          { t: 'Saber si un dibuix fet a mà és un gat|Saber si un dibujo hecho a mano es un gato', b: 1 },
          { t: 'Encendre els llums del pati a les 8 del vespre|Encender las luces del patio a las 8 de la tarde', b: 0 },
          { t: "Traduir un missatge del català a l'anglès|Traducir un mensaje del castellano al inglés", b: 1 }],
        ex: "Si el problema és exacte i el pots descriure del tot, les regles guanyen. Si és ple de matisos (veus, imatges, gustos, llengua), cal aprendre d'exemples.|Si el problema es exacto y lo puedes describir del todo, las reglas ganan. Si está lleno de matices (voces, imágenes, gustos, lengua), hay que aprender de ejemplos." },
      { k: 'iachat', ph: 'investiga', q: "Aquest xatbot del menjador només fa servir <b>regles de paraules clau</b>. Fes-li preguntes i <b>marca amb la 🚩 la resposta equivocada</b>.|Este chatbot del comedor solo usa <b>reglas de palabras clave</b>. Hazle preguntas y <b>marca con la 🚩 la respuesta equivocada</b>.",
        bot: { n: 'CantinaBot|CantinaBot', av: '🍽️' }, live: false, need: 1, topic: 'El menú del menjador|El menú del comedor',
        tip: "Pista: fixa't si la resposta respon de veritat el que has preguntat.|Pista: fíjate en si la respuesta responde de verdad lo que has preguntado.",
        nodes: [
          { id: 'a', msg: ["Hola! Soc el CantinaBot. Pregunta'm pel menú del menjador.|¡Hola! Soy el CantinaBot. Pregúntame por el menú del comedor."], opts: [{ t: 'Què hi ha per dinar avui?|¿Qué hay para comer hoy?', go: 'b' }] },
          { id: 'b', msg: [{ t: 'Avui: macarrons amb tomàquet i, de postres, iogurt.|Hoy: macarrones con tomate y, de postre, yogur.', ok: "Correcte: la pregunta conté «dinar» i «avui», i la regla respon el menú d'avui.|Correcto: la pregunta contiene «comer» y «hoy», y la regla responde el menú de hoy." }],
            opts: [{ t: "No m'agrada la pasta. Hi ha alguna altra cosa?|No me gusta la pasta. ¿Hay alguna otra cosa?", go: 'c' }, { t: 'I demà, què hi ha per dinar?|¿Y mañana qué hay para comer?', go: 'c2' }] },
          { id: 'c', msg: [{ t: 'Bona notícia: avui hi ha pasta! Macarrons amb tomàquet 🍝|¡Buena noticia: hoy hay pasta! Macarrones con tomate 🍝', bad: "La regla busca la paraula «pasta» i respon el menú. No entén el «no m'agrada»: una regla de paraules clau no capta el sentit de la frase.|La regla busca la palabra «pasta» y responde el menú. No entiende el «no me gusta»: una regla de palabras clave no capta el sentido de la frase." }],
            opts: [{ t: 'Tinc al·lèrgia a la llet. Puc menjar el iogurt?|Tengo alergia a la leche. ¿Puedo comer el yogur?', go: 'd' }] },
          { id: 'c2', msg: [{ t: 'Avui: macarrons amb tomàquet i, de postres, iogurt.|Hoy: macarrones con tomate y, de postre, yogur.', bad: "Has preguntat per demà! La regla ha trobat «dinar» i ha respost el menú d'avui: ningú no li havia escrit cap regla per a «demà».|¡Has preguntado por mañana! La regla ha encontrado «comer» y ha respondido el menú de hoy: nadie le había escrito ninguna regla para «mañana»." }],
            opts: [{ t: 'Tinc al·lèrgia a la llet. Puc menjar el iogurt?|Tengo alergia a la leche. ¿Puedo comer el yogur?', go: 'd' }] },
          { id: 'd', end: true, msg: [{ t: "No t'entenc. Prova amb: «menú», «avui» o «postres».|No te entiendo. Prueba con: «menú», «hoy» o «postre».", ok: "Aquí no s'inventa res: com que no té cap regla per a les al·lèrgies, ho diu. Millor això que una resposta inventada! Per a una al·lèrgia, pregunta sempre a una persona.|Aquí no se inventa nada: como no tiene ninguna regla para las alergias, lo dice. ¡Mejor eso que una respuesta inventada! Para una alergia, pregunta siempre a una persona." }],
            fb: "Les regles són previsibles, però es trenquen quan la pregunta canvia una mica. Una IA que aprèn d'exemples entendria més maneres de preguntar… però es podria equivocar d'altres maneres.|Las reglas son previsibles, pero se rompen cuando la pregunta cambia un poco. Una IA que aprende de ejemplos entendería más maneras de preguntar… pero se podría equivocar de otras maneras." }] },
      { k: 'quiz', ph: 'investiga', q: 'Per què el CantinaBot ha respost malament?|¿Por qué el CantinaBot ha respondido mal?',
        opts: ["Només mira si hi ha certes paraules, no què vol dir la frase|Solo mira si hay ciertas palabras, no qué quiere decir la frase", "Perquè té poques dades d'entrenament|Porque tiene pocos datos de entrenamiento", 'Perquè la temperatura és massa alta|Porque la temperatura es demasiado alta'], a: 0,
        ex: "No té dades ni temperatura: és un programa de regles. Per arreglar-lo caldrien regles i més regles… i sempre en faltaria alguna.|No tiene datos ni temperatura: es un programa de reglas. Para arreglarlo harían falta reglas y más reglas… y siempre faltaría alguna." },
      { k: 'move', ph: 'pausa', title: "Pausa activa: la regla del pingüí|Pausa activa: la regla del pingüino", secs: 45,
        t: "Dempeus! Regla: si dic un animal que vola, aixequeu els braços; si neda, feu ones amb les mans. Àliga… dofí… mosca… I un pingüí? Les regles també dubten amb els casos especials!|¡De pie! Regla: si digo un animal que vuela, levantad los brazos; si nada, haced olas con las manos. Águila… delfín… mosca… ¿Y un pingüino? ¡Las reglas también dudan con los casos especiales!" },
      { k: 'iatrain', ph: 'repte', q: "<b>Reaccions dibuixades:</b> en una xarxa social inventada reacciones dibuixant amb el dit. Dibuixa 5 cors i 5 estrelles i fes que la IA encerti almenys un 80 %.|<b>Reacciones dibujadas:</b> en una red social inventada reaccionas dibujando con el dedo. Dibuja 5 corazones y 5 estrellas y haz que la IA acierte al menos un 80 %.",
        srcs: ['draw', 'data'], classes: [{ n: 'Cor|Corazón', ico: '❤️', g: 'heart' }, { n: 'Estrella|Estrella', ico: '⭐', g: 'star' }], test: { n: 8 },
        checks: [{ k: 'perclass', min: 5 }, { k: 'acc', min: .8 }],
        pro: { q: "<b>Quatre reaccions:</b> cor, estrella, llamp i creu. Dona-li 5 exemples de cada i fes que encerti almenys un 85 %. Escriure regles per a això seria un malson!|<b>Cuatro reacciones:</b> corazón, estrella, rayo y cruz. Dale 5 ejemplos de cada y haz que acierte al menos un 85 %. ¡Escribir reglas para esto sería una pesadilla!",
          classes: [{ n: 'Cor|Corazón', ico: '❤️', g: 'heart' }, { n: 'Estrella|Estrella', ico: '⭐', g: 'star' }, { n: 'Llamp|Rayo', ico: '⚡', g: 'zig' }, { n: 'Creu|Cruz', ico: '❌', g: 'cross' }],
          checks: [{ k: 'perclass', min: 5 }, { k: 'acc', min: .85 }] } },
      { k: 'quiz', ph: 'repte', q: "El filtre de regles ja té 50 regles (gratis, gr4tis, gr@tis…). Ara els missatges trampa escriuen «g-r-a-t-i-s». Quina solució aguanta millor?|El filtro de reglas ya tiene 50 reglas (gratis, gr4tis, gr@tis…). Ahora los mensajes trampa escriben «g-r-a-t-i-s». ¿Qué solución aguanta mejor?",
        opts: ["Un model entrenat amb molts missatges trampa recents, que es torna a entrenar sovint|Un modelo entrenado con muchos mensajes trampa recientes, que se vuelve a entrenar a menudo", 'Escriure la regla número 51|Escribir la regla número 51', 'Apagar el filtre|Apagar el filtro'], a: 0,
        ex: "Els filtres d'spam de veritat aprenen d'exemples i es tornen a entrenar, perquè els trucs canvien sense parar. Sovint també hi afegeixen algunes regles fixes.|Los filtros de spam de verdad aprenden de ejemplos y se vuelven a entrenar, porque los trucos cambian sin parar. A menudo también añaden algunas reglas fijas." },
      { k: 'iatrain', ph: 'repte', q: "<b>Comandament per sons:</b> un aplaudiment passa la diapositiva i un xiulet torna enrere. Entrena la IA amb sons i fes que encerti almenys un 80 %.|<b>Mando por sonidos:</b> un aplauso pasa la diapositiva y un silbido vuelve atrás. Entrena la IA con sonidos y haz que acierte al menos un 80 %.",
        srcs: ['data', 'mic'], classes: [{ n: 'Aplaudiment|Aplauso', ico: '👏', g: 'clap' }, { n: 'Xiulet|Silbido', ico: '😗', g: 'whistle' }], test: { n: 8 },
        checks: [{ k: 'perclass', min: 5 }, { k: 'acc', min: .8 }],
        pro: { q: "<b>Comandament complet:</b> aplaudiment, xiulet, veu i soroll de fons (perquè no s'activi sol). Fes que encerti almenys un 90 %.|<b>Mando completo:</b> aplauso, silbido, voz y ruido de fondo (para que no se active solo). Haz que acierte al menos un 90 %.",
          classes: [{ n: 'Aplaudiment|Aplauso', ico: '👏', g: 'clap' }, { n: 'Xiulet|Silbido', ico: '😗', g: 'whistle' }, { n: 'Veu|Voz', ico: '🗣️', g: 'voice' }, { n: 'Soroll de fons|Ruido de fondo', ico: '🤫', g: 'noise' }],
          checks: [{ k: 'perclass', min: 5 }, { k: 'acc', min: .9 }] } },
      { k: 'quiz', ph: 'repte', extra: true, q: "⭐ Una app de deures ha de comprovar sumes i també llegir la lletra feta a mà. Com ho faries?|⭐ Una app de deberes tiene que comprobar sumas y también leer la letra hecha a mano. ¿Cómo lo harías?",
        opts: ["Regles per comprovar la suma i un model après d'exemples per llegir la lletra|Reglas para comprobar la suma y un modelo aprendido de ejemplos para leer la letra", 'Tot amb regles|Todo con reglas', "Tot amb un model après d'exemples, també per sumar|Todo con un modelo aprendido de ejemplos, también para sumar"], a: 0,
        ex: "Cada part amb l'eina que li va millor: sumar és exacte (regles); la lletra de cada persona és diferent (exemples).|Cada parte con la herramienta que mejor le va: sumar es exacto (reglas); la letra de cada persona es distinta (ejemplos)." },
      { k: 'iatrain', ph: 'crea', free: true, srcs: ['draw'], save: true, name: 'Els meus símbols secrets|Mis símbolos secretos',
        q: "<b>Els teus símbols secrets.</b> Inventa 3 símbols (canvia'ls el nom si vols), dibuixa'n almenys 6 de cada i fes la prova dibuixant-ne de nous. Prova d'escriure'n les regles… impossible, oi?|<b>Tus símbolos secretos.</b> Inventa 3 símbolos (cámbiales el nombre si quieres), dibuja al menos 6 de cada y haz la prueba dibujando otros nuevos. Intenta escribir sus reglas… imposible, ¿verdad?",
        classes: [{ n: 'Llamp|Rayo' }, { n: 'Espiral|Espiral' }, { n: 'Onada|Ola' }], test: { n: 3 },
        checks: [{ k: 'classes', min: 3 }, { k: 'perclass', min: 6 }, { k: 'test' }] },
      { k: 'quiz', ph: 'tanca', q: 'Quina frase és certa?|¿Qué frase es cierta?',
        opts: ["Les regles fallen amb casos nous; els exemples fallen si les dades són dolentes|Las reglas fallan con casos nuevos; los ejemplos fallan si los datos son malos", "Aprendre d'exemples sempre és millor|Aprender de ejemplos siempre es mejor", 'Les regles ja no es fan servir|Las reglas ya no se usan'], a: 0,
        ex: "Cadascuna té el seu lloc, i sovint es fan servir juntes.|Cada una tiene su sitio, y a menudo se usan juntas." },
      { k: 'quiz', ph: 'tanca', q: 'La IA ha reconegut el teu símbol. Pots saber exactament per què?|La IA ha reconocido tu símbolo. ¿Puedes saber exactamente por qué?',
        opts: ["No del tot: ha comparat amb els exemples més semblants, però no hi ha cap regla escrita per llegir|No del todo: ha comparado con los ejemplos más parecidos, pero no hay ninguna regla escrita que leer", 'Sí: sempre explica la regla que ha fet servir|Sí: siempre explica la regla que ha usado', "No, perquè ho fa a l'atzar|No, porque lo hace al azar"], a: 0,
        ex: "Amb la nostra IA pots veure els 5 veïns més propers. En una xarxa neuronal enorme, entendre per què decideix és molt més difícil: hi ha tot un camp d'investigació, la IA explicable.|Con nuestra IA puedes ver los 5 vecinos más cercanos. En una red neuronal enorme, entender por qué decide es mucho más difícil: hay todo un campo de investigación, la IA explicable." },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 3 · Probabilitats i prediccions ---------- */
  { id: 'i1-3', t: 'Probabilitats i prediccions|Probabilidades y predicciones', min: 50, badge: 'i_temp',
    learn: ["Un model de llenguatge calcula la probabilitat de cada fitxa possible, en tria una, l'afegeix i torna a començar: així escriu textos sencers.|Un modelo de lenguaje calcula la probabilidad de cada ficha posible, elige una, la añade y vuelve a empezar: así escribe textos enteros.",
      "La temperatura canvia com tria: baixa, gairebé sempre la més probable; alta, s'arrisca. Per això un xat d'IA pot respondre diferent a la mateixa pregunta.|La temperatura cambia cómo elige: baja, casi siempre la más probable; alta, se arriesga. Por eso un chat de IA puede responder distinto a la misma pregunta.",
      "Que un text soni bé no vol dir que sigui cert: el model tria el que és probable segons les dades, no el que és veritat.|Que un texto suene bien no quiere decir que sea cierto: el modelo elige lo que es probable según los datos, no lo que es verdad."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: 'Per reconèixer cors i estrelles dibuixats, què vas fer servir?|Para reconocer corazones y estrellas dibujados, ¿qué usaste?',
        opts: ['Exemples etiquetats|Ejemplos etiquetados', 'Regles escrites a mà|Reglas escritas a mano', 'Una calculadora|Una calculadora'], a: 0,
        ex: "Avui tornem als models de llenguatge, que també aprenen d'exemples: de textos.|Hoy volvemos a los modelos de lenguaje, que también aprenden de ejemplos: de textos." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'estudi', title: 'El comentarista robòtic|El comentarista robótico',
        t: "La ràdio de l'institut vol un <b>comentarista robòtic</b> per a la lliga del pati. Avui l'entrenaràs amb cròniques inventades, faràs que triï les paraules amb més o menys risc… i descobriràs per què pot explicar un gol que no ha passat mai.|La radio del instituto quiere un <b>comentarista robótico</b> para la liga del patio. Hoy lo entrenarás con crónicas inventadas, harás que elija las palabras con más o menos riesgo… y descubrirás por qué puede contar un gol que no ha pasado nunca." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Pas a pas|Paso a paso', t: 'Una fitxa, i una altra, i una altra…|Una ficha, y otra, y otra…', anim: 'i13loop',
          x: "El model mira el text, calcula la probabilitat de cada fitxa possible, en tria una i l'afegeix al final. Ara el text és més llarg: torna a calcular. El bucle es repeteix fins que tria un punt final. Cada fitxa nova depèn de totes les d'abans.|El modelo mira el texto, calcula la probabilidad de cada ficha posible, elige una y la añade al final. Ahora el texto es más largo: vuelve a calcular. El bucle se repite hasta que elige un punto final. Cada ficha nueva depende de todas las anteriores." },
        { k: 'Context|Contexto', t: 'Quantes paraules mira enrere?|¿Cuántas palabras mira atrás?', anim: 'i13ctx',
          x: "Si el model només mira «blau», no sap si parla del porter o del davanter. Si mira «porter blau», l'encerta. Com més <b>context</b> té en compte, millors prediccions. El nostre en mira 1, 2 o 3 paraules; els models grans poden tenir en compte textos llarguíssims.|Si el modelo solo mira «azul», no sabe si habla del portero o del delantero. Si mira «portero azul», acierta. Cuanto más <b>contexto</b> tiene en cuenta, mejores predicciones. El nuestro mira 1, 2 o 3 palabras; los modelos grandes pueden tener en cuenta textos larguísimos." },
        { k: 'Temperatura|Temperatura', t: 'Afilar o aplanar les probabilitats|Afilar o aplanar las probabilidades', anim: 'i13temp2',
          x: "Abans de triar, la temperatura transforma les probabilitats. <b>Baixa</b> (0,2): la més probable s'ho emporta gairebé tot. <b>1</b>: es queden igual. <b>Alta</b> (2): s'aplanen i les paraules rares tenen més opcions. Llavors el model sorteja segons aquestes probabilitats.|Antes de elegir, la temperatura transforma las probabilidades. <b>Baja</b> (0,2): la más probable se lo lleva casi todo. <b>1</b>: se quedan igual. <b>Alta</b> (2): se aplanan y las palabras raras tienen más opciones. Entonces el modelo sortea según esas probabilidades.",
          tip: "Per això, si fas la mateixa pregunta dues vegades a un xat d'IA, la resposta pot canviar: tria amb una mica d'atzar.|Por eso, si haces la misma pregunta dos veces a un chat de IA, la respuesta puede cambiar: elige con un poco de azar." },
        { k: 'A gran escala|A gran escala', t: "Com s'entrena un model gran|Cómo se entrena un modelo grande", anim: 'i13train',
          x: "1) <b>Preentrenament</b>: llegeix una quantitat enorme de text i aprèn a predir la fitxa següent, amb una xarxa neuronal de milers de milions de números (paràmetres). 2) Persones li ensenyen exemples de bones respostes. 3) Persones valoren respostes i el model s'ajusta per donar les més ben valorades. Alguns models també practiquen amb problemes que es poden comprovar, com mates o codi.|1) <b>Preentrenamiento</b>: lee una cantidad enorme de texto y aprende a predecir la ficha siguiente, con una red neuronal de miles de millones de números (parámetros). 2) Personas le enseñan ejemplos de buenas respuestas. 3) Personas valoran respuestas y el modelo se ajusta para dar las mejor valoradas. Algunos modelos también practican con problemas que se pueden comprobar, como mates o código." },
        { k: 'Compte!|¡Cuidado!', t: 'Fluid no vol dir cert|Fluido no quiere decir cierto', anim: 'i13fluent',
          x: "El model tria la fitxa <b>probable</b>, no la <b>veritable</b>. Pot enganxar trossos de textos diferents i fer una frase perfecta… i falsa. Per això, quan una IA et dona una dada, un nom o una xifra, cal comprovar-ho en una font fiable.|El modelo elige la ficha <b>probable</b>, no la <b>verdadera</b>. Puede pegar trozos de textos distintos y hacer una frase perfecta… y falsa. Por eso, cuando una IA te da un dato, un nombre o una cifra, hay que comprobarlo en una fuente fiable." }
      ] },
      { k: 'unplug', ph: 'mans', ico: '📄', title: 'Paraules plegades|Palabras dobladas', t: "En files de 5 o 6, amb un full en blanc per fila. Fareu de model de llenguatge… amb molt poca memòria.|En filas de 5 o 6, con una hoja en blanco por fila. Haréis de modelo de lenguaje… con muy poca memoria.",
        steps: ["La primera persona escriu el començament d'una crònica, «La davantera…», i plega el full perquè només es vegi l'última paraula.|La primera persona escribe el comienzo de una crónica, «La delantera…», y dobla la hoja para que solo se vea la última palabra.",
          "La següent llegeix només aquesta paraula, n'escriu una que hi pugui anar darrere i torna a plegar. Així fins al final de la fila.|La siguiente lee solo esa palabra, escribe una que pueda ir detrás y vuelve a doblar. Así hasta el final de la fila.",
          'Desplegueu-lo i llegiu la frase en veu alta. Té sentit?|Desdobladla y leed la frase en voz alta. ¿Tiene sentido?',
          'Repetiu-ho deixant veure les 3 últimes paraules. Què canvia?|Repetidlo dejando ver las 3 últimas palabras. ¿Qué cambia?'],
        tip: "Amb una paraula de context sou un model de bigrames; amb tres, el text és molt més coherent. Els models grans en veuen milers.|Con una palabra de contexto sois un modelo de bigramas; con tres, el texto es mucho más coherente. Los modelos grandes ven miles." },
      { k: 'quiz', ph: 'prova', q: "Després de «xuta i…», el model calcula: <b>gol 50 %</b>, <b>fora 30 %</b>, <b>pal 20 %</b>. Amb temperatura 0, què escriurà?|Después de «chuta y…», el modelo calcula: <b>gol 50 %</b>, <b>fuera 30 %</b>, <b>palo 20 %</b>. Con temperatura 0, ¿qué escribirá?",
        opts: ['Sempre «gol»|Siempre «gol»', '«gol» la meitat de les vegades|«gol» la mitad de las veces', "Qualsevol de les tres, igual de probables|Cualquiera de las tres, igual de probables"], a: 0,
        ex: "Amb temperatura 0 tria sempre la més probable. Amb temperatura 1, «gol» sortiria més o menys la meitat de les vegades.|Con temperatura 0 elige siempre la más probable. Con temperatura 1, «gol» saldría más o menos la mitad de las veces.",
        pro: { q: "Amb <b>gol 50 %</b>, <b>fora 30 %</b> i <b>pal 20 %</b>, el model genera 100 cròniques a temperatura 1. Quantes vegades, més o menys, escriurà «pal»?|Con <b>gol 50 %</b>, <b>fuera 30 %</b> y <b>palo 20 %</b>, el modelo genera 100 crónicas a temperatura 1. ¿Cuántas veces, más o menos, escribirá «palo»?",
          opts: ['Unes 20|Unas 20', 'Cap|Ninguna', 'Unes 50|Unas 50'], a: 0,
          ex: "A temperatura 1 sorteja amb les probabilitats tal com són: el 20 % de 100 són unes 20 vegades (pot variar una mica per l'atzar). A temperatura 0, cap.|A temperatura 1 sortea con las probabilidades tal como son: el 20 % de 100 son unas 20 veces (puede variar un poco por el azar). A temperatura 0, ninguna." } },
      { k: 'iangram', ph: 'prova', q: "<b>Genera cròniques</b> començant per «la davantera»: una amb temperatura baixa (≤ 0,4) i una amb alta (≥ 1,4). Quina sona més de veritat?|<b>Genera crónicas</b> empezando por «la delantera»: una con temperatura baja (≤ 0,4) y una con alta (≥ 1,4). ¿Cuál suena más de verdad?",
        text: "la davantera xuta i marca. la davantera xuta i marca un gol. la davantera xuta i la pilota surt fora. el porter atura la pilota. el porter salta i atura. la grada canta. la grada salta i canta. l'àrbitra xiula el final. l'equip blau celebra el gol.|la delantera chuta y marca. la delantera chuta y marca un gol. la delantera chuta y el balón sale fuera. el portero para el balón. el portero salta y para. la grada canta. la grada salta y canta. la árbitra pita el final. el equipo azul celebra el gol.",
        ctx: 'la davantera|la delantera', checks: [{ k: 'temp' }],
        pro: { n: 3, orders: [2, 3], q: "Posa el model a mirar <b>2 paraules enrere</b> i genera amb temperatura baixa (≤ 0,4) i alta (≥ 1,4). Les cròniques són més coherents?|Pon el modelo a mirar <b>2 palabras atrás</b> y genera con temperatura baja (≤ 0,4) y alta (≥ 1,4). ¿Las crónicas son más coherentes?",
          checks: [{ k: 'temp' }, { k: 'order', min: 3 }] } },
      { k: 'iangram', ph: 'investiga', q: "Aquest model ha llegit <b>dues cròniques</b> de partits diferents. Genera 3 textos des de «l'equip verd» i busca'n un que soni bé però sigui <b>fals</b>.|Este modelo ha leído <b>dos crónicas</b> de partidos distintos. Genera 3 textos desde «el equipo verde» y busca uno que suene bien pero sea <b>falso</b>.",
        text: "diumenge l'equip verd ha perdut tres a u. l'Ona ha marcat l'únic gol de l'equip verd. dissabte l'equip blau ha guanyat dos a zero. en Pau ha marcat dos gols de cap. l'equip blau ha celebrat la victòria amb la grada.|el domingo el equipo verde ha perdido tres a uno. Ona ha marcado el único gol del equipo verde. el sábado el equipo azul ha ganado dos a cero. Pau ha marcado dos goles de cabeza. el equipo azul ha celebrado la victoria con la grada.",
        ctx: "l'equip verd|el equipo verde", checks: [{ k: 'gen', min: 3 }] },
      { k: 'quiz', ph: 'investiga', q: "El model ha escrit: «l'equip verd ha guanyat dos a zero». D'on ha sortit?|El modelo ha escrito: «el equipo verde ha ganado dos a cero». ¿De dónde ha salido?",
        opts: ["Ha enganxat trossos de les dues cròniques: després de «ha» pot venir «perdut» o «guanyat»|Ha pegado trozos de las dos crónicas: después de «ha» puede venir «perdido» o «ganado»", "Sap que l'equip verd va guanyar|Sabe que el equipo verde ganó", "S'ha espatllat|Se ha estropeado"], a: 0,
        ex: "La frase és fluida perquè cada parella de paraules és a les dades, però el conjunt és fals: el model no comprova fets. A gran escala, això és una «al·lucinació» d'un xat d'IA.|La frase es fluida porque cada pareja de palabras está en los datos, pero el conjunto es falso: el modelo no comprueba hechos. A gran escala, esto es una «alucinación» de un chat de IA." },
      { k: 'move', ph: 'pausa', title: 'Pausa activa: el termòmetre|Pausa activa: el termómetro', secs: 45,
        t: "Dempeus! Quan diguem «temperatura 0», tothom fa el mateix gest: braços amunt. Quan diguem «temperatura 2», cadascú fa el gest que vulgui, com més original millor. Tres rondes!|¡De pie! Cuando digamos «temperatura 0», todo el mundo hace el mismo gesto: brazos arriba. Cuando digamos «temperatura 2», cada uno hace el gesto que quiera, cuanto más original mejor. ¡Tres rondas!" },
      { k: 'iangram', ph: 'repte', q: "Després de «el porter blau», el model diu «marca»… perquè només mira «blau». <b>Fes-lo mirar 2 paraules enrere</b> perquè guanyi «atura».|Después de «el portero azul», el modelo dice «marca»… porque solo mira «azul». <b>Hazlo mirar 2 palabras atrás</b> para que gane «para».",
        text: "el porter blau atura. el porter blau atura la pilota. el porter blau salta. el davanter blau marca. el davanter blau marca un gol. el davanter blau marca de cap. el davanter blau xuta.|el portero azul para. el portero azul para el balón. el portero azul salta. el delantero azul marca. el delantero azul marca un gol. el delantero azul marca de cabeza. el delantero azul chuta.",
        n: 2, orders: [2, 3], ctx: 'el porter blau|el portero azul',
        checks: [{ k: 'top', ctx: 'el porter blau|el portero azul', next: 'atura|para' }, { k: 'order', min: 3 }],
        pro: { orders: [2, 3, 4], q: "Fes que el model miri <b>2 o més paraules enrere</b> perquè després de «el porter blau» guanyi «atura», i genera amb temperatura baixa i alta.|Haz que el modelo mire <b>2 o más palabras atrás</b> para que después de «el portero azul» gane «para», y genera con temperatura baja y alta.",
          checks: [{ k: 'top', ctx: 'el porter blau|el portero azul', next: 'atura|para' }, { k: 'order', min: 3 }, { k: 'temp' }] } },
      { k: 'quiz', ph: 'repte', q: 'Fas la mateixa pregunta dues vegades a un xat d\'IA i et respon amb paraules diferents. Per què?|Haces la misma pregunta dos veces a un chat de IA y te responde con palabras distintas. ¿Por qué?',
        opts: ["Tria cada fitxa amb una mica d'atzar (temperatura més gran que 0)|Elige cada ficha con un poco de azar (temperatura mayor que 0)", "Ha après coses noves entre una pregunta i l'altra|Ha aprendido cosas nuevas entre una pregunta y otra", "S'ha enfadat|Se ha enfadado"], a: 0,
        ex: "Mentre el fas servir, el model no canvia: el que canvia és l'atzar en triar. Amb temperatura 0 les respostes s'assemblarien molt més (tot i que, per detalls tècnics, no sempre surten idèntiques).|Mientras lo usas, el modelo no cambia: lo que cambia es el azar al elegir. Con temperatura 0 las respuestas se parecerían mucho más (aunque, por detalles técnicos, no siempre salen idénticas)." },
      { k: 'iangram', ph: 'repte', extra: true, unit: 'char', n: 4, q: "⭐ Aquest model aprèn <b>lletres</b> de noms de grups de música inventats. Genera noms nous amb temperatura baixa i alta. Quin triaries per al teu grup?|⭐ Este modelo aprende <b>letras</b> de nombres de grupos de música inventados. Genera nombres nuevos con temperatura baja y alta. ¿Cuál elegirías para tu grupo?",
        text: 'neó lunar. neó salvatge. lluna de neó. els lunàtics. raig de neó. lluna salvatge. kids del neó. els salvatges. ràdio lunar. la tribu del raig.|neón lunar. neón salvaje. luna de neón. los lunáticos. rayo de neón. luna salvaje. kids del neón. los salvajes. radio lunar. la tribu del rayo.',
        ctx: 'lu|lu', checks: [{ k: 'temp' }] },
      { k: 'iangram', ph: 'crea', edit: true, orders: [2, 3], save: true, name: 'El meu comentarista|Mi comentarista',
        q: "<b>El teu comentarista.</b> Tria un esport, afegeix al final almenys 3 frases teves (fins a 70 fitxes) i genera amb temperatura baixa i alta.|<b>Tu comentarista.</b> Elige un deporte, añade al final al menos 3 frases tuyas (hasta 70 fichas) y genera con temperatura baja y alta.",
        texts: [
          { n: '⚽ Futbol|⚽ Fútbol', x: "la davantera rep la pilota. la davantera dribla i xuta. quin gol més bonic. el porter no hi arriba. la grada canta el nom de l'equip. l'àrbitra mira el rellotge. quin final de partit.|la delantera recibe el balón. la delantera regatea y chuta. qué gol más bonito. el portero no llega. la grada canta el nombre del equipo. la árbitra mira el reloj. qué final de partido." },
          { n: '🏀 Bàsquet|🏀 Baloncesto', x: "la base puja la pilota. la base passa a la pivot. la pivot salta i esmaixa. quina esmaixada. el públic s'aixeca. falten deu segons. triple i victòria.|la base sube el balón. la base pasa a la pívot. la pívot salta y machaca. qué mate. el público se levanta. faltan diez segundos. triple y victoria." },
          { n: '🎮 E-sports|🎮 E-sports', x: "l'equip lila ataca per l'esquerra. la capitana dona l'ordre. quina estratègia. l'equip groc es defensa. el comentarista crida. queda un minut. l'equip lila guanya la final.|el equipo lila ataca por la izquierda. la capitana da la orden. qué estrategia. el equipo amarillo se defiende. el comentarista grita. queda un minuto. el equipo lila gana la final." }],
        ctx: 'la|la',
        sol: "la davantera torna a xutar. quin gol més espectacular. la grada salta i canta. el porter mira la pilota a la xarxa. l'equip celebra la victòria al mig del camp.|la delantera vuelve a chutar. qué gol más espectacular. la grada salta y canta. el portero mira el balón en la red. el equipo celebra la victoria en el centro del campo.",
        checks: [{ k: 'words', min: 70 }, { k: 'temp' }],
        pro: { q: "<b>El teu comentarista (PRO).</b> Afegeix-hi frases teves (fins a 70 fitxes), fes que miri 2 paraules enrere i genera amb temperatura baixa i alta.|<b>Tu comentarista (PRO).</b> Añade frases tuyas (hasta 70 fichas), haz que mire 2 palabras atrás y genera con temperatura baja y alta.",
          checks: [{ k: 'words', min: 70 }, { k: 'temp' }, { k: 'order', min: 3 }] } },
      { k: 'quiz', ph: 'tanca', q: 'Com escriu un text llarg un model de llenguatge?|¿Cómo escribe un texto largo un modelo de lenguaje?',
        opts: ['Fitxa a fitxa: calcula probabilitats, en tria una i repeteix|Ficha a ficha: calcula probabilidades, elige una y repite', 'Copia una resposta sencera que té guardada|Copia una respuesta entera que tiene guardada', 'Busca el text a internet i el copia|Busca el texto en internet y lo copia'], a: 0,
        ex: "Per dins hi ha moltíssims càlculs, però el que en surt és sempre la fitxa següent, una darrere l'altra.|Por dentro hay muchísimos cálculos, pero lo que sale es siempre la ficha siguiente, una detrás de otra." },
      { k: 'quiz', ph: 'tanca', q: 'Per a quina tasca triaries una temperatura baixa?|¿Para qué tarea elegirías una temperatura baja?',
        opts: ['Resumir els apunts de manera fiable|Resumir los apuntes de forma fiable', 'Inventar noms per a un grup de música|Inventar nombres para un grupo de música', 'Escriure un poema surrealista|Escribir un poema surrealista'], a: 0,
        ex: "Quan vols precisió, baixa. Quan vols idees noves, alta… i després hi poses el teu criteri.|Cuando quieres precisión, baja. Cuando quieres ideas nuevas, alta… y después le pones tu criterio." },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 4 · Projecte: un model amb el teu estil ---------- */
  { id: 'i1-4', t: 'Projecte: un model amb el teu estil|Proyecto: un modelo con tu estilo', min: 55, proj: true, badge: 'i_style',
    learn: ["Un model de llenguatge s'assembla a les dades que llegeix: si el corpus té un estil clar, el model l'imita.|Un modelo de lenguaje se parece a los datos que lee: si el corpus tiene un estilo claro, el modelo lo imita.",
      "Amb poques dades el model copia frases senceres; amb més dades i més variades, combina trossos i en fa de noves.|Con pocos datos el modelo copia frases enteras; con más datos y más variados, combina trozos y hace otras nuevas.",
      "Presentar un model és explicar què fa bé, on falla i per què: els límits també formen part del projecte.|Presentar un modelo es explicar qué hace bien, dónde falla y por qué: los límites también forman parte del proyecto."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: 'Què passa si poses el model a mirar més paraules enrere?|¿Qué pasa si pones el modelo a mirar más palabras atrás?',
        opts: ['Les frases són més coherents, però amb poques dades copia més el text original|Las frases son más coherentes, pero con pocos datos copia más el texto original', "Ja no s'equivoca mai|Ya no se equivoca nunca", 'Escriu més ràpid|Escribe más rápido'], a: 0,
        ex: "Ho comprovaràs avui amb el teu propi model.|Lo comprobarás hoy con tu propio modelo." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'estudi', title: 'El teu propi model|Tu propio modelo',
        t: "Projecte de la unitat: crearàs un <b>mini model de llenguatge amb estil</b>. El xat d'una classe inventada, la lletra d'una cançó que escriviu vosaltres, un comentarista, un narrador de vídeos de cuina… L'entrenaràs, el provaràs i el presentaràs: què ha après i on falla.|Proyecto de la unidad: crearás un <b>mini modelo de lenguaje con estilo</b>. El chat de una clase inventada, la letra de una canción que escribáis vosotros, un comentarista, un narrador de vídeos de cocina… Lo entrenarás, lo probarás y lo presentarás: qué ha aprendido y dónde falla." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Corpus|Corpus', t: "Les dades fan l'estil|Los datos hacen el estilo", anim: 'i14corpus',
          x: "El <b>corpus</b> és el conjunt de textos amb què entrenes el model. Un bon corpus té un estil clar (com parla el personatge), expressions que es repeteixen i prou varietat. I res de dades personals: noms inventats, cap adreça ni telèfon.|El <b>corpus</b> es el conjunto de textos con el que entrenas el modelo. Un buen corpus tiene un estilo claro (cómo habla el personaje), expresiones que se repiten y bastante variedad. Y nada de datos personales: nombres inventados, ninguna dirección ni teléfono." },
        { k: 'Copiar o crear|Copiar o crear', t: 'Memoritzar no és aprendre|Memorizar no es aprender', anim: 'i14memo',
          x: "Amb poques dades, cada paraula només té una continuació i el model repeteix frases senceres: les ha <b>memoritzat</b>. Amb més dades i més variades, hi ha cruïlles i el model combina trossos: <b>generalitza</b>. Als models grans també els passa: de vegades reprodueixen textos que han llegit molt.|Con pocos datos, cada palabra solo tiene una continuación y el modelo repite frases enteras: las ha <b>memorizado</b>. Con más datos y más variados, hay cruces y el modelo combina trozos: <b>generaliza</b>. A los modelos grandes también les pasa: a veces reproducen textos que han leído mucho." },
        { k: 'Avaluar|Evaluar', t: 'Com saps si el teu model és bo?|¿Cómo sabes si tu modelo es bueno?', anim: 'i14eval',
          x: "Prova'l amb començaments i temperatures diferents i compta: quantes frases tenen sentit? quantes s'assemblen a l'estil? quantes són còpies exactes del corpus? Apunta-ho: és la teva avaluació, com fan els equips que creen models de veritat.|Pruébalo con comienzos y temperaturas distintos y cuenta: ¿cuántas frases tienen sentido? ¿cuántas se parecen al estilo? ¿cuántas son copias exactas del corpus? Apúntalo: es tu evaluación, como hacen los equipos que crean modelos de verdad." },
        { k: 'Autoria|Autoría', t: 'Els textos tenen autor|Los textos tienen autor', anim: 'i14rights',
          x: "Les cançons, els llibres i les notícies tenen autors i drets. Hi ha un debat obert, i judicis, sobre si es poden fer servir per entrenar IA sense permís. Al projecte, fes-ho bé: escriu tu el corpus o fes servir textos que puguis fer servir, i digues d'on surten.|Las canciones, los libros y las noticias tienen autores y derechos. Hay un debate abierto, y juicios, sobre si se pueden usar para entrenar IA sin permiso. En el proyecto, hazlo bien: escribe tú el corpus o usa textos que puedas usar, y di de dónde salen." }
      ] },
      { k: 'unplug', ph: 'mans', ico: '✍️', title: 'El corpus en paper|El corpus en papel', t: 'En parelles, amb el full «Pla del meu model».|En parejas, con la hoja «Plan de mi modelo».',
        steps: ["Trieu un estil: el xat d'una classe inventada, una cançó, un comentarista, un narrador de receptes, un youtuber de ciència…|Elegid un estilo: el chat de una clase inventada, una canción, un comentarista, un narrador de recetas, un youtuber de ciencia…",
          "Escriviu 10 frases curtes amb aquest estil. Repetiu algunes expressions típiques, com faria el personatge.|Escribid 10 frases cortas con ese estilo. Repetid algunas expresiones típicas, como haría el personaje.",
          'Prediu: quines 3 paraules sortiran més? Després de quina paraula hi haurà més varietat?|Predecid: ¿qué 3 palabras saldrán más? ¿Después de qué palabra habrá más variedad?',
          'Reviseu-ho: cap nom real, cap dada personal, cap text copiat.|Revisadlo: ningún nombre real, ningún dato personal, ningún texto copiado.'],
        tip: "Les expressions repetides són les que el model aprendrà primer: són la «firma» de l'estil.|Las expresiones repetidas son las que el modelo aprenderá primero: son la «firma» del estilo." },
      { k: 'quiz', ph: 'prova', q: 'Quin corpus funcionarà millor per a un model amb estil de comentarista?|¿Qué corpus funcionará mejor para un modelo con estilo de comentarista?',
        opts: ['40 frases curtes de cròniques escrites per vosaltres, amb expressions que es repeteixen|40 frases cortas de crónicas escritas por vosotros, con expresiones que se repiten', 'Tres frases molt llargues|Tres frases muy largas', 'Les converses reals del grup de la classe, amb noms i telèfons|Las conversaciones reales del grupo de la clase, con nombres y teléfonos'], a: 0,
        ex: "Moltes frases amb un estil clar, i escrites per vosaltres. Les converses reals tenen dades personals: mai a un corpus.|Muchas frases con un estilo claro, y escritas por vosotros. Las conversaciones reales tienen datos personales: nunca en un corpus." },
      { k: 'iangram', ph: 'repte', q: "Amb aquesta cançó el model <b>només copia</b>: després de «ballem» sempre ve «fins». Afegeix versos perquè «fins» baixi al 50 % o menys i el model conegui 30 paraules.|Con esta canción el modelo <b>solo copia</b>: después de «bailamos» siempre viene «hasta». Añade versos para que «hasta» baje al 50 % o menos y el modelo conozca 30 palabras.",
        text: "llums de neó a la ciutat. llums de neó a la ciutat. ballem fins que surti el sol. ballem fins que surti el sol. tu i jo sota la lluna.|luces de neón en la ciudad. luces de neón en la ciudad. bailamos hasta que salga el sol. bailamos hasta que salga el sol. tú y yo bajo la luna.",
        ctx: 'ballem|bailamos',
        add: ['ballem sota la pluja.|bailamos bajo la lluvia.', 'ballem amb la llum de la lluna.|bailamos con la luz de la luna.', 'ballem al ritme del cor.|bailamos al ritmo del corazón.', 'ballem a la terrassa amb tu.|bailamos en la terraza contigo.', 'la ciutat brilla de nit.|la ciudad brilla de noche.', 'el sol surt darrere del mar.|el sol sale detrás del mar.'],
        checks: [{ k: 'prob', ctx: 'ballem|bailamos', next: 'fins|hasta', max: .5 }, { k: 'vocab', min: 30 }],
        pro: { n: 3, orders: [2, 3], q: "Afegeix versos perquè «fins» baixi al 50 % o menys i el model conegui 30 paraules. Després fes-lo mirar 2 paraules enrere i genera amb temperatura baixa i alta: copia més o menys?|Añade versos para que «hasta» baje al 50 % o menos y el modelo conozca 30 palabras. Después hazlo mirar 2 palabras atrás y genera con temperatura baja y alta: ¿copia más o menos?",
          checks: [{ k: 'prob', ctx: 'ballem|bailamos', next: 'fins|hasta', max: .5 }, { k: 'vocab', min: 30 }, { k: 'order', min: 3 }, { k: 'temp' }] } },
      { k: 'quiz', ph: 'investiga', q: "Poses el model a mirar 3 paraules enrere amb un corpus de 40 paraules, i el text generat és idèntic a frases del corpus. Per què?|Pones el modelo a mirar 3 palabras atrás con un corpus de 40 palabras, y el texto generado es idéntico a frases del corpus. ¿Por qué?",
        opts: ['Amb tant de context i tan poques dades, cada tros només té una continuació: copia|Con tanto contexto y tan pocos datos, cada trozo solo tiene una continuación: copia', 'Perquè la temperatura és 0|Porque la temperatura es 0', 'Perquè ha entès la cançó|Porque ha entendido la canción'], a: 0,
        ex: "Per combinar, el model necessita cruïlles: llocs on una mateixa seqüència té diverses continuacions. Més context demana més dades.|Para combinar, el modelo necesita cruces: lugares donde una misma secuencia tiene varias continuaciones. Más contexto pide más datos." },
      { k: 'move', ph: 'pausa', title: 'Pausa activa: la coreografia del model|Pausa activa: la coreografía del modelo', secs: 60,
        t: "Dempeus en rotllana! Cadascú fa un moviment que encaixi amb el de la persona d'abans (només mira el d'abans). Després, repetiu-ho mirant els 3 d'abans. Surt una coreografia més coherent?|¡De pie en corro! Cada uno hace un movimiento que encaje con el de la persona de antes (solo mira el de antes). Después, repetidlo mirando los 3 de antes. ¿Sale una coreografía más coherente?" },
      { k: 'quiz', ph: 'repte', q: "En Marc vol entrenar el seu model amb la lletra sencera d'una cançó famosa i penjar-lo a internet. Què li recomanes?|Marc quiere entrenar su modelo con la letra entera de una canción famosa y colgarlo en internet. ¿Qué le recomiendas?",
        opts: ["Escriure'n una de pròpia, o fer servir textos que pugui fer servir, i dir d'on surten|Escribir una propia, o usar textos que pueda usar, y decir de dónde salen", "Endavant: si és a internet, és de tothom|Adelante: si está en internet, es de todos", 'Canviar dues paraules perquè no es noti|Cambiar dos palabras para que no se note'], a: 0,
        ex: "Que un text sigui a internet no vol dir que el puguis fer servir com vulguis: té autoria. Entrenar IA amb textos amb drets és un debat obert.|Que un texto esté en internet no quiere decir que lo puedas usar como quieras: tiene autoría. Entrenar IA con textos con derechos es un debate abierto." },
      { k: 'iangram', ph: 'repte', extra: true, q: "⭐ <b>Mescla d'estils:</b> el model de receptes ha après de cuina. Afegeix-li frases de comentarista perquè després de «afegim» guanyi «un»… i genera una recepta comentada!|⭐ <b>Mezcla de estilos:</b> el modelo de recetas ha aprendido de cocina. Añádele frases de comentarista para que después de «añadimos» gane «un»… ¡y genera una receta comentada!",
        text: "primer afegim la sal. després afegim la farina. remenem la massa amb calma. afegim l'oli i remenem. al final tastem la recepta.|primero añadimos la sal. después añadimos la harina. removemos la masa con calma. añadimos el aceite y removemos. al final probamos la receta.",
        ctx: 'afegim|añadimos',
        add: ["afegim un gol a l'últim minut!|¡añadimos un gol en el último minuto!", 'afegim un xut potent des del mig del camp!|¡añadimos un chut potente desde el centro del campo!', 'atenció, afegim un gol de cap espectacular!|¡atención, añadimos un gol de cabeza espectacular!'],
        checks: [{ k: 'top', ctx: 'afegim|añadimos', next: 'un|un' }, { k: 'gen' }] },
      { k: 'iangram', ph: 'crea', edit: true, orders: [2, 3, 4], save: true, name: 'El meu model amb estil|Mi modelo con estilo',
        q: "<b>El teu model amb estil.</b> Escriu el teu corpus (almenys 80 fitxes i 40 paraules diferents), prova'l amb 3 generacions i genera amb temperatura baixa i alta.|<b>Tu modelo con estilo.</b> Escribe tu corpus (al menos 80 fichas y 40 palabras distintas), pruébalo con 3 generaciones y genera con temperatura baja y alta.",
        text: 'Escriu aquí el teu corpus.|Escribe aquí tu corpus.', ctx: '',
        sol: "bon dia, cuiners i cuineres. avui fem una truita de patates. primer pelem les patates amb calma. després tallem les patates i la ceba. ara escalfem l'oli a la paella. ara fregim les patates a foc lent. mentrestant batem els ous amb una mica de sal. ara barregem les patates amb els ous. després girem la truita amb un plat gran. i ja ho tenim: una truita daurada i suau. si us ha agradat, prepareu-la a casa. fins a la propera recepta, cuiners i cuineres. avui la cuina fa olor de festa. ara toca netejar la paella. recordeu: amb calma, la cuina surt més bona.|buenos días, cocineros y cocineras. hoy hacemos una tortilla de patatas. primero pelamos las patatas con calma. después cortamos las patatas y la cebolla. ahora calentamos el aceite en la sartén. ahora freímos las patatas a fuego lento. mientras tanto batimos los huevos con un poco de sal. ahora mezclamos las patatas con los huevos. después giramos la tortilla con un plato grande. y ya lo tenemos: una tortilla dorada y suave. si os ha gustado, preparadla en casa. hasta la próxima receta, cocineros y cocineras. hoy la cocina huele a fiesta. ahora toca limpiar la sartén. recordad: con calma, la cocina sale más buena.",
        checks: [{ k: 'words', min: 80 }, { k: 'vocab', min: 40 }, { k: 'gen', min: 3 }, { k: 'temp' }],
        pro: { q: "<b>El teu model amb estil (PRO).</b> Un corpus d'almenys 120 fitxes i 55 paraules diferents. Fes-lo mirar 2 o més paraules enrere i genera amb temperatura baixa i alta.|<b>Tu modelo con estilo (PRO).</b> Un corpus de al menos 120 fichas y 55 palabras distintas. Hazlo mirar 2 o más palabras atrás y genera con temperatura baja y alta.",
          checks: [{ k: 'words', min: 120 }, { k: 'vocab', min: 55 }, { k: 'order', min: 3 }, { k: 'temp' }] } },
      { k: 'review', ph: 'crea', q: "<b>Prepara la presentació:</b> respon sobre el teu model. Es desarà al teu perfil.|<b>Prepara la presentación:</b> responde sobre tu modelo. Se guardará en tu perfil.", btn: 'Desa la fitxa|Guarda la ficha',
        items: [
          { q: 'Quin estil imita el teu model?|¿Qué estilo imita tu modelo?', opts: ["El xat d'una classe inventada|El chat de una clase inventada", 'Una cançó pròpia|Una canción propia', 'Un comentarista|Un comentarista', 'Un narrador o youtuber|Un narrador o youtuber'] },
          { q: 'Quina temperatura li va millor?|¿Qué temperatura le va mejor?', opts: ['Baixa: més coherent|Baja: más coherente', "Mitjana, al voltant d'1|Media, alrededor de 1", 'Alta: més original|Alta: más original'] },
          { q: 'Quantes paraules enrere funciona millor?|¿Cuántas palabras atrás funciona mejor?', opts: ['1 paraula|1 palabra', '2 paraules|2 palabras', '3 paraules|3 palabras'] },
          { q: 'Quin límit has trobat?|¿Qué límite has encontrado?', opts: ['Copia frases senceres del corpus|Copia frases enteras del corpus', 'Barreja coses i diu frases falses|Mezcla cosas y dice frases falsas', 'No sap res que no sigui a les dades|No sabe nada que no esté en los datos', 'Frases sense sentit amb temperatura alta|Frases sin sentido con temperatura alta'] },
          { q: 'Com el milloraries?|¿Cómo lo mejorarías?', opts: ['Més textos i més variats|Más textos y más variados', 'Mirar més paraules enrere (amb més dades)|Mirar más palabras atrás (con más datos)', 'Revisar que no hi hagi dades personals ni textos copiats|Revisar que no haya datos personales ni textos copiados'] }] },
      { k: 'unplug', ph: 'crea', ico: '🎤', title: 'Presentació en 60 segons|Presentación en 60 segundos', t: 'Cada parella presenta el seu model a un altre grup en un minut.|Cada pareja presenta su modelo a otro grupo en un minuto.',
        steps: ["Ensenyeu el corpus: quin estil té i qui l'ha escrit.|Enseñad el corpus: qué estilo tiene y quién lo ha escrito.",
          "Genereu en directe dos textos: un a temperatura baixa i un a temperatura alta.|Generad en directo dos textos: uno a temperatura baja y uno a temperatura alta.",
          "Expliqueu què ha après bé i un límit que hi heu trobat.|Explicad qué ha aprendido bien y un límite que habéis encontrado.",
          "L'altre grup diu una cosa que li ha agradat i una idea per millorar-lo.|El otro grupo dice una cosa que le ha gustado y una idea para mejorarlo."],
        tip: "Una bona presentació d'un model sempre diu on falla. Això no és un fracàs: és honestedat.|Una buena presentación de un modelo siempre dice dónde falla. Eso no es un fracaso: es honestidad." },
      { k: 'quiz', ph: 'tanca', q: 'El teu model ha generat una frase que no és enlloc del corpus. Com és possible?|Tu modelo ha generado una frase que no está en ningún sitio del corpus. ¿Cómo es posible?',
        opts: ['Ha combinat trossos de frases diferents que comparteixen paraules|Ha combinado trozos de frases distintas que comparten palabras', "L'ha buscada a internet|La ha buscado en internet", 'És impossible: sempre copia|Es imposible: siempre copia'], a: 0,
        ex: "Això és generalitzar: fer servir el que ha après en combinacions noves.|Esto es generalizar: usar lo aprendido en combinaciones nuevas." },
      { k: 'quiz', ph: 'tanca', q: 'Què és el més important quan presentes un model?|¿Qué es lo más importante cuando presentas un modelo?',
        opts: ['Explicar què fa bé i també on falla|Explicar qué hace bien y también dónde falla', "Dir que no s'equivoca mai|Decir que no se equivoca nunca", 'Ensenyar només els millors textos|Enseñar solo los mejores textos'], a: 0,
        ex: "Els equips que publiquen models seriosos també n'expliquen els límits. A la unitat 2 en faràs una fitxa.|Los equipos que publican modelos serios también explican sus límites. En la unidad 2 harás una ficha." },
      { k: 'feel', ph: 'tanca' }
    ] }
] };
